  mothership_chassis: ['chassis_chronos', 'chassis_eclipse', 'chassis_leviathan', 'chassis_ragnarok', 'chassis_sovereign', 'chassis_vanguard'],
  nemesis: ['nemesis-1', 'nemesis-10', 'nemesis-11', 'nemesis-2', 'nemesis-3', 'nemesis-4', 'nemesis-5', 'nemesis-6', 'nemesis-7', 'nemesis-8', 'nemesis-9'],
