  relics: ['relic_anubis_crystal_matrix', 'relic_ark_of_truth', 'relic_asgard_computer_core', 'relic_atanik_armband', 'relic_crystal_skull', 'relic_dakara_superweapon', 'relic_dakara_transmuter_shard', 'relic_destiny_master_glyph', 'relic_eye_of_ra', 'relic_kara_kesh', 'relic_lantean_drone_crystal', 'relic_neutrino_generator', 'relic_nox_healing_crystal', 'relic_quantum_mirror', 'relic_sangreal_grail', 'relic_tollan_phase_shift', 'relic_wraith_stunner', 'relic_zero_point_module'],
